#!/bin/sh
# CC0: This work has been marked as dedicated to the public domain.
# debian-maintenance.sh: dash shim for `util debian-maintenance [--report]`.
# It owns --help and --build/--version, then execs the perl program
# util/debian-maintenance/debian-maintenance.pl (whose header documents the implementation),
# passing its own resolved path in DEBIAN_MAINTENANCE_SHIM for sudo self-elevation.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'util/debian-maintenance.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'debian-maintenance.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -eu
for _a in "$@"; do case "$_a" in --help|-h)
	printf 'usage: %s [--report]\n' "${0##*/}"
	printf '%s\n' 'Interactive APT maintenance (root, TTY); --report prints a read-only JSON posture report.'
	exit 0;; esac; done
self=$(readlink -f "$0")
here=$(dirname "$self")
case " $* " in *" --build "*|*" --version "*)
	# shellcheck source=util/lib/build-id.sh
	. "$here/lib/build-id.sh"; build_flags "$0" "$@";; esac
DEBIAN_MAINTENANCE_SHIM=$self
export DEBIAN_MAINTENANCE_SHIM
exec perl "$here/debian-maintenance/debian-maintenance.pl" "$@"
